style.css:
@-moz-document domain("example.com") {
/* Global Box Sizing for Consistency */
    * {
        box-sizing: border-box;
    }

    /* Sidebar Styling for All Screen Sizes */
    main .sidebar {
        display: grid;
        grid-gap: 15px;
        grid-area: sidebar;
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
        align-content: start;
        padding-bottom: 15px;
        word-wrap: break-word;
    }

    /* Responsive Sidebar for Medium Screens */
    @media (min-width: 768px) and (max-width: 991px) {
        main .sidebar {
            margin: 0 15px;
        }
    }

    /* Theme Colors for Red Theme */
    .theme-red {
        --f-primary-color: #8c2f2f;
        --f-primary-color-hover: #c0837e;
        --f-primary-color-active: #b42318;
        --f-primary-color-active-rgb: 180, 35, 24; /* Direct RGB value */
        --f-secondary: #fecdca;
        --f-secondary-text: #ffbcb7;
        --f-text-color: #ff9c95;
        --f-light-bg: #e8c0c0;
        --f-light-bg-hover: #fee4e2;
    }

    /* Global Display for Divs */
    div {
        display: block;
        unicode-bidi: isolate;
    }
}
